<script setup lang="ts">
import { computed, onUnmounted, ref, watch } from "vue";
import { useAuth } from "@papilio/auth";
import { item, request, query, type Page, type SmsSettlementCandidate, type SmsManualApproval, type SmsSettlementReview, type SmsOriginCapabilities } from "@papilio/api";
import { faNumber } from "@papilio/ui";
import { useI18n } from "vue-i18n";
import { useLocalizedFormats } from "../../composables/useLocalizedFormats";
const props=defineProps<{eventId:number;capabilities:SmsOriginCapabilities|null}>();
const emit=defineEmits<{busy:[value:boolean]}>();
const { t } = useI18n();
const { date: formatDate, toman: formatToman } = useLocalizedFormats();
const auth=useAuth(),review=ref<SmsSettlementReview|null>(null),loading=ref(false),busy=ref(false),error=ref("");
const labels=computed(()=>({manual:t("payments.settlement.manual"),waiting:t("payments.settlement.waiting"),ambiguous:t("payments.settlement.ambiguous"),approved:t("payments.settlement.linked"),outside_window:t("payments.settlement.outsideWindow")}));
const candidates=ref<SmsSettlementCandidate[]>([]),candidatePage=ref(1),candidatePages=ref(1),candidateLoading=ref(false),candidateError=ref(""),selected=ref<SmsSettlementCandidate|null>(null),reason=ref(""),pendingBody=ref<SmsManualApproval|null>(null),approvalError=ref(""),approvalNotice=ref("");
const revisionsReady=computed(()=>review.value?.device_revision!=null&&review.value.realm_revision!=null&&review.value.destination_revision!=null);
const canApprove=computed(()=>props.capabilities?.enabled&&auth.can("payments","update")&&review.value?.manual_approval_available&&selected.value?.selectable&&revisionsReady.value&&reason.value.trim().length>0);
let alive=true,sequence=0,candidateSequence=0;
async function loadCandidates():Promise<void>{if(!props.capabilities?.capacity)return;const id=props.eventId,key=++candidateSequence;candidateLoading.value=true;candidateError.value="";try{const result=await request<Page<SmsSettlementCandidate>>(`/v1/admin/payments/sms-origins/sms-events/${id}/candidates?${query({page:candidatePage.value})}`);if(!alive||key!==candidateSequence||props.eventId!==id)return;candidates.value=result.data;candidatePages.value=result.meta.pager?.total_pages??1;}catch(cause){if(alive&&key===candidateSequence)candidateError.value=failure(cause);}finally{if(alive&&key===candidateSequence)candidateLoading.value=false;}}
function choose(row:SmsSettlementCandidate):void{if(busy.value||pendingBody.value||!row.selectable)return;selected.value=row;approvalError.value="";approvalNotice.value="";}
function adoptRevisions():void{const body=pendingBody.value,current=review.value;if(!body||!current||!revisionsReady.value||busy.value||current.status==='approved')return;pendingBody.value={...body,expected_device_revision:current.device_revision!,expected_realm_revision:current.realm_revision!,expected_destination_revision:current.destination_revision!};}
async function approve():Promise<void>{if(busy.value||!props.capabilities?.enabled||!auth.can("payments","update"))return;if(!pendingBody.value){if(!canApprove.value||!selected.value||!review.value)return;pendingBody.value={topup_id:selected.value.topup_id,expected_device_revision:review.value.device_revision!,expected_realm_revision:review.value.realm_revision!,expected_destination_revision:review.value.destination_revision!,reason:reason.value.trim()};}const id=props.eventId,body={...pendingBody.value},key=++sequence;loading.value=false;busy.value=true;emit("busy",true);approvalError.value="";approvalNotice.value="";try{const result=await item<SmsSettlementReview>(`/v1/admin/payments/sms-origins/sms-events/${id}/approve`,"POST",body);if(!alive||props.eventId!==id||key!==sequence)return;if(result.sms_event_id!==id||result.status==='approved'&&result.topup_id!==body.topup_id)throw new Error(t("payments.settlement.foreignReceipt"));review.value=result;if(result.status==='approved'){pendingBody.value=null;approvalNotice.value=result.topup_id===body.topup_id?t("payments.settlement.receiptLinked"):t("payments.settlement.alreadyLinkedDifferent");}else approvalNotice.value=t("payments.settlement.held");await loadCandidates();}catch(cause){if(alive)approvalError.value=failure(cause);}finally{if(alive){busy.value=false;emit("busy",false);}}}

function failure(cause:unknown):string{return cause instanceof Error?cause.message:t("errors.request_failed");}
async function load():Promise<void>{const id=props.eventId,key=++sequence;loading.value=true;error.value="";try{const result=await item<SmsSettlementReview>(`/v1/admin/payments/sms-origins/sms-events/${id}/review`);if(alive&&key===sequence&&props.eventId===id){if(result.sms_event_id!==id)throw new Error(t("payments.settlement.mismatchedRead"));review.value=result;}}catch(cause){if(alive&&key===sequence)error.value=failure(cause);}finally{if(alive&&key===sequence)loading.value=false;}}
async function check():Promise<void>{if(pendingBody.value||busy.value||!props.capabilities?.enabled||!auth.can("payments","update"))return;const id=props.eventId,key=++sequence;loading.value=false;busy.value=true;emit("busy",true);error.value="";try{const result=await item<SmsSettlementReview>(`/v1/admin/payments/sms-origins/sms-events/${id}/review/refresh`,"POST");if(alive&&key===sequence&&props.eventId===id){if(result.sms_event_id!==id)throw new Error(t("payments.settlement.mismatchedRead"));review.value=result;}}catch(cause){if(alive&&key===sequence)error.value=failure(cause);}finally{if(alive){busy.value=false;emit("busy",false);}}}
watch(()=>props.eventId,()=>{review.value=null;selected.value=null;pendingBody.value=null;reason.value="";candidatePage.value=1;candidates.value=[];void load();void loadCandidates();},{immediate:true});onUnmounted(()=>{alive=false;++sequence;++candidateSequence;});
</script>
<template><section class="review-section" :aria-label="t('payments.settlement.section')"><div class="page-head"><h3>{{ t("payments.settlement.title") }}</h3><button class="btn secondary" :disabled="loading||busy" @click="load">{{ t('payments.settlement.reload') }}</button></div><p v-if="loading" role="status">{{ t('payments.settlement.loading') }}</p><p v-if="error" class="message error" role="alert">{{error}}</p><template v-if="review"><p class="hint-box">{{ t("payments.settlement.hint") }}</p><dl class="review-grid"><div><dt>{{ t("payments.settlement.lastDecision") }}</dt><dd>{{labels[review.status]}}</dd></div><div><dt>{{ t("payments.settlement.lastChecked") }}</dt><dd>{{review.checked_at===null?t('payments.settlement.notChecked'):formatDate(review.checked_at)}}</dd></div><div><dt>{{ t("payments.settlement.reason") }}</dt><dd><code>{{review.reason_code??t('payments.settlement.noHoldReason')}}</code></dd></div><div><dt>{{ t("payments.settlement.candidateCount") }}</dt><dd>{{faNumber(review.candidate_count)}}</dd></div><div><dt>{{ t("payments.settlement.linkedPayment") }}</dt><dd>{{review.topup_id===null?t('payments.settlement.noLink'):t('payments.paymentLabel',{id:String(review.topup_id)})}} / {{review.settlement_id===null?t('payments.settlement.noSettlement'):'#'+review.settlement_id}}</dd></div><div><dt>{{ t("payments.settlement.evidence") }}</dt><dd>{{review.evidence_kind==='bank_reference'?t('payments.sms.bankEvidence'):review.evidence_kind==='trusted_sms_origin'?t('payments.sms.trustedEvidence'):t('payments.sms.notRecorded')}}</dd></div><div><dt>{{ t("payments.settlement.deviceRevision") }}</dt><dd>{{review.device_id??t('payments.sms.notRecorded')}} / {{review.device_revision??t('payments.sms.unavailableTime')}}</dd></div><div><dt>{{ t("payments.settlement.receivingRevision") }}</dt><dd>{{review.receiving_realm_id??t('payments.sms.notRecorded')}} / {{review.realm_revision??t('payments.sms.unavailableTime')}}</dd></div><div><dt>{{ t("payments.settlement.destinationRevision") }}</dt><dd>{{review.destination_id??t('payments.sms.notRecorded')}} / {{review.destination_revision??t('payments.sms.unavailableTime')}}</dd></div></dl></template><template v-if="capabilities?.enabled&&auth.can('payments','update')"><p class="hint-box">{{ t("payments.settlement.runCheckHint") }}</p><button class="btn secondary" :disabled="loading||busy||pendingBody!==null" @click="check">{{ t('payments.settlement.runCheck') }}</button></template><section v-if="capabilities?.capacity" :aria-label="t('payments.settlement.candidates')"><h3>{{ t("payments.settlement.candidates") }}</h3><p class="hint-box">{{ t("payments.settlement.candidatesHint") }}</p><p v-if="candidateError" class="message error" role="alert">{{candidateError}}</p><p v-if="candidateLoading" role="status">{{ t('payments.settlement.loadingCandidates') }}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>{{ t("payments.settlement.paymentCustomer") }}</th><th>{{ t("payments.amount") }}</th><th>{{ t("payments.status") }}</th><th>{{ t("payments.settlement.association") }}</th><th>{{ t("payments.settlement.updated") }}</th><th></th></tr></thead><tbody><tr v-for="row in candidates" :key="row.topup_id"><td>{{ t('payments.paymentLabel',{id:String(row.topup_id)}) }} · {{ t('payments.customerLabel',{id:String(row.customer_id)}) }}</td><td>{{formatToman(row.amount_rial)}}</td><td>{{row.status==='approved'?t('payments.settlement.alreadyCredited'):t('payments.settlement.pendingPayment')}}{{row.already_linked?' · '+t('payments.settlement.alreadyLinked'):''}}</td><td>{{row.association_kind==='captured_realm'?t('payments.settlement.capturedAccount'):row.association_kind==='immutable_instruction'?t('payments.settlement.capturedInstruction'):t('payments.settlement.unresolved')}}</td><td>{{formatDate(row.updated_at)}}</td><td><button v-if="auth.can('payments','update')" class="btn small secondary" :disabled="busy||pendingBody!==null||!row.selectable||!capabilities.enabled" @click="choose(row)">{{selected?.topup_id===row.topup_id?t('payments.settlement.selected'):row.selectable?t('payments.settlement.select'):t('payments.settlement.notSelectable')}}</button></td></tr></tbody></table></div><p v-if="!candidateLoading&&!candidates.length&&!candidateError">{{ t('payments.settlement.noCandidates') }}</p><div class="pager"><button :disabled="candidateLoading||busy||candidatePage<=1" @click="candidatePage--;loadCandidates()">‹</button><span>{{faNumber(candidatePage)}} / {{faNumber(candidatePages)}}</span><button :disabled="candidateLoading||busy||candidatePage>=candidatePages" @click="candidatePage++;loadCandidates()">›</button></div><button class="btn secondary" :disabled="candidateLoading||busy" @click="loadCandidates">{{ t('payments.settlement.reloadCandidates') }}</button><form v-if="selected&&auth.can('payments','update')" class="form-grid" @submit.prevent="approve"><p>{{ t('payments.selectedPayment',{id:String(selected.topup_id)}) }} · {{formatToman(selected.amount_rial)}} · {{selected.status==='approved'?t('payments.settlement.selectedApproved'):t('payments.settlement.selectedPending')}}</p><label class="field"><span>{{ t("payments.settlement.reasonLabel") }}</span><textarea v-model="reason" maxlength="1000" required :disabled="busy||pendingBody!==null"/></label><p v-if="pendingBody" class="hint-box">{{ t("payments.settlement.retainedHint", { payment: pendingBody.topup_id, device: pendingBody.expected_device_revision, realm: pendingBody.expected_realm_revision, destination: pendingBody.expected_destination_revision }) }}</p><p v-if="approvalError" class="message error" role="alert">{{approvalError}}</p><p v-if="approvalNotice" class="message" role="status">{{approvalNotice}}</p><button class="btn" :disabled="busy||!capabilities.enabled||!pendingBody&&!canApprove">{{pendingBody?t('payments.settlement.retryRetained'):selected.status==='approved'?t('payments.settlement.attachExisting'):t('payments.settlement.approveSelected')}}</button><button v-if="pendingBody&&revisionsReady&&review?.status!=='approved'" type="button" class="btn secondary" :disabled="busy" @click="adoptRevisions">{{ t('payments.settlement.useCurrentRevisions') }}</button></form></section></section></template>
<style scoped>.review-section{margin-top:24px;padding-top:20px;border-top:1px solid var(--line)}.review-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:16px}.review-grid dt{color:var(--muted);font-size:.85rem}.review-grid dd{margin:4px 0 0;overflow-wrap:anywhere}</style>
